import{_ as e,c as i,e as p,a as n,d as t,w as l,r,o as d,b as o}from"./app-CHV3pEDi.js";const c="/assets/%E8%A3%B8%E6%9C%BA%E4%B8%BB%E5%BE%AA%E7%8E%AF%E8%BD%AE%E8%AF%A2%E6%B5%81%E7%A8%8B%E5%9B%BE-BY-7-Anx.jpg",m="/assets/%E5%B5%8C%E5%85%A5%E5%BC%8F%E6%93%8D%E4%BD%9C%E7%B3%BB%E7%BB%9F%E5%88%86%E5%B1%82%E7%BB%93%E6%9E%84%E5%9B%BE-uutZN11p.jpg",h="/assets/RTOS%E5%A4%9A%E4%BB%BB%E5%8A%A1%E7%8B%AC%E7%AB%8B%E8%BF%90%E8%A1%8C%E7%BB%93%E6%9E%84%E5%9B%BE-waUoIt-1.jpg",u="/assets/%E6%8A%A2%E5%8D%A0%E5%BC%8F%E4%B8%8A%E4%B8%8B%E6%96%87%E5%88%87%E6%8D%A2%E6%97%B6%E5%BA%8F%E5%9B%BE-CKter7VI.jpg",v={};function g(E,s){const a=r("VPLink");return d(),i("div",null,[s[4]||(s[4]=p(`<p>很多同学在第一次接触单片机开发时，写出来的程序几乎都是同一个样子：在 main 函数里完成各种初始化操作，然后进入到一个 while (1) 大循环中，并在该循环中不停地执行轮询按键、读取传感器、刷新屏幕等工作。</p><p>当项目简单的时候，这种写法没有任何问题，逻辑上比较简单且较好调试。不过，随着功能一点点增加，你可能会发现出现按键偶尔失灵、传感器采样间隔忽长忽短、串口数据一多整个程序就像卡住了一样等异常情况。</p><p>由此可见，当项目逐渐变复杂，我们就不得不面对这样一个问题：有没有一种更合理的方式来组织整个程序？这正是嵌入式操作系统要解决的问题。</p><h2 id="一、先看看没有操作系统时-程序是怎么写的" tabindex="-1"><a class="header-anchor" href="#一、先看看没有操作系统时-程序是怎么写的"><span>一、先看看没有操作系统时，程序是怎么写的</span></a></h2><p>不使用任何操作系统的程序通常被称为裸机程序。这种程序最常见的架构，就是一个无限主循环，在这个循环中把所有事情依次做一遍，下面给出了一串简单的示例代码：</p><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;"><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code"><code class="language-"><span class="line"><span>int main(void)</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>   hardware_init();</span></span>
<span class="line"><span>   while (1)</span></span>
<span class="line"><span>   {</span></span>
<span class="line"><span>       key_scan();        /* 扫描按键 */</span></span>
<span class="line"><span>       sensor_read();     /* 读取传感器 */</span></span>
<span class="line"><span>       display_update();  /* 刷新显示 */</span></span>
<span class="line"><span>       uart_send();       /* 串口发送数据 */</span></span>
<span class="line"><span>   }</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>这种结构的问题在于：<strong>所有功能共享同一条执行路径，如果任何一个函数执行得慢了，后面的事情都得排队等着。</strong><img src="`+c+'" alt="裸机主循环轮询流程图"></p><p>有的同学可能会想到，引入中断，把紧急的事情放到中断服务函数里处理，从而形成 &quot;主循环加中断&quot; 的前后台结构。不过，中断只能处理单个事件，多个功能模块之间的并发关系依然要靠我们用大量全局变量和状态标志去手工维护，功能越多越容易出错。</p><p>所以，这种架构并不是万能的。</p><p>有的同学可能会结合自己以往的经验，开发出一种新的程序架构。也有的同学可能会直接选择市面上成熟的程序架构，比如嵌入式操作系统。</p><h2 id="二、嵌入式操作系统到底是什么" tabindex="-1"><a class="header-anchor" href="#二、嵌入式操作系统到底是什么"><span>二、嵌入式操作系统到底是什么</span></a></h2><p>简单来说，<strong>嵌入式操作系统就是运行在嵌入式设备上、夹在硬件和应用程序之间的一层管理软件，它把 CPU、内存、中断、外设这些硬件资源统一管理起来，再以服务的形式提供给上层应用</strong>。 <img src="'+m+`" alt="嵌入式操作系统分层结构图"></p><p>不过，我们平常在开发中使用的是，常常是RTOS（Real Time Operating System），即嵌入式操作系统中的实时操作系统，比如 FreeRTOS、RT-Thread、μC/OS、Zephyr等。</p><p>这种操作系统虽然和我们电脑上的 Windows、Linux 属于同一类概念，但设计目标完全不同。嵌入式设备的内存和算力通常非常有限，所以该系统必须足够小巧、可以按需裁剪。</p><p>此外，<strong>RTOS 最核心的追求是确定性</strong>。这种确定性并不是要求系统运行的速度很快，而是要保证关键任务必须在规定的时间内得到响。</p><h2 id="三、它是怎么让多个任务-同时运行-的" tabindex="-1"><a class="header-anchor" href="#三、它是怎么让多个任务-同时运行-的"><span>三、它是怎么让多个任务 &quot;同时运行&quot; 的</span></a></h2><p>与祼机程序不同，<strong>RTOS可以将一个一个完整的应用拆分成若干个相对独立的任务，每个任务有自己的优先级和专属的栈空间，并且都写成无限循环的形式</strong>。</p><p>以常见的 RTOS 写法为例，当需要一秒钟采集一次温湿度时，可以创建如下所示的任务：</p><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;"><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code"><code class="language-"><span class="line"><span>void sensor_task(void *arg)</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>   while (1)</span></span>
<span class="line"><span>  {</span></span>
<span class="line"><span>       read_temp_humi();</span></span>
<span class="line"><span>       vTaskDelay(pdMS_TO_TICKS(1000));</span></span>
<span class="line"><span>   }</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>这样一来，整个系统就可以根据需要创建多个任务，每个任务可以专心做自己的事情，可以减少不同功能模块之间的相互干扰。 <img src="`+h+'" alt="RTOS多任务独立运行结构图"></p><p>在RTOS内部，系统依靠一个周期性的时钟节拍（Tick）来推动时间运转，调度器会按照优先级决定此刻该让哪个任务占用 CPU。</p><p>例如，当高优先级任务就绪时，它会立刻抢占低优先级任务，RTOS把当前任务的寄存器和栈指针保存到它自己的栈上，再把高优先级任务的现场恢复出来继续执行。这个保存和恢复的过程叫做上下文切换，整个切换发生在很短的时间内，于是在我们看来，多个任务就像在同时运行一样。 <img src="'+u+'" alt="抢占式上下文切换时序图"></p><h2 id="四、总结" tabindex="-1"><a class="header-anchor" href="#四、总结"><span>四、总结</span></a></h2><p>综上所述，所谓嵌入式操作系统，就是运行在资源受限的嵌入式设备上、统一管理硬件资源并为应用提供任务调度、内存管理、中断处理和任务间通信等服务的一层系统软件。</p><p>其中 ，RTOS 凭借基于优先级的抢占式调度，保证了关键任务响应的确定性，把裸机程序中难以维护的并发逻辑变成了清晰的多任务模型。</p><hr>',26)),n("blockquote",null,[s[1]||(s[1]=n("p",null,"如果你希望系统地学习RTOS底层原理，可以了解我的《RTOS开发与实战》课程。",-1)),s[2]||(s[2]=n("p",null,"课程不是简单地讲解FreeRTOS API的使用，而是带你从零开始编写一个RTOS内核，逐步实现任务管理、任务调度、上下文切换、同步与通信等核心机制，并通过一个远程温湿度监控设备项目，将操作系统原理应用到实际嵌入式开发中。",-1)),s[3]||(s[3]=n("p",null,"适合希望深入理解RTOS工作原理、提升嵌入式底层开发能力的同学。",-1)),n("p",null,[t(a,{href:"/blog/diyrtos/"},{default:l(()=>[...s[0]||(s[0]=[o("课程详情",-1)])]),_:1})])])])}const b=e(v,[["render",g]]),k=JSON.parse('{"path":"/tech/rtos100/vgpmdp08/","title":"什么是嵌入式操作系统","lang":"zh-CN","frontmatter":{"title":"什么是嵌入式操作系统","createTime":"2026/11/10 14:55:11","permalink":"/tech/rtos100/vgpmdp08/","description":"很多同学在第一次接触单片机开发时，写出来的程序几乎都是同一个样子：在 main 函数里完成各种初始化操作，然后进入到一个 while (1) 大循环中，并在该循环中不停地执行轮询按键、读取传感器、刷新屏幕等工作。 当项目简单的时候，这种写法没有任何问题，逻辑上比较简单且较好调试。不过，随着功能一点点增加，你可能会发现出现按键偶尔失灵、传感器采样间隔忽长...","head":[["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"什么是嵌入式操作系统\\",\\"image\\":[\\"\\"],\\"dateModified\\":null,\\"author\\":[]}"],["meta",{"property":"og:url","content":"https://lishutong1024.cn/tech/rtos100/vgpmdp08/"}],["meta",{"property":"og:site_name","content":"李述铜的嵌入式课堂"}],["meta",{"property":"og:title","content":"什么是嵌入式操作系统"}],["meta",{"property":"og:description","content":"很多同学在第一次接触单片机开发时，写出来的程序几乎都是同一个样子：在 main 函数里完成各种初始化操作，然后进入到一个 while (1) 大循环中，并在该循环中不停地执行轮询按键、读取传感器、刷新屏幕等工作。 当项目简单的时候，这种写法没有任何问题，逻辑上比较简单且较好调试。不过，随着功能一点点增加，你可能会发现出现按键偶尔失灵、传感器采样间隔忽长..."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:locale","content":"zh-CN"}]]},"readingTime":{"minutes":5.28,"words":1585},"git":{},"autoDesc":true,"filePathRelative":"notes/tech/rtos100/base/q01.md","headers":[],"bulletin":true}');export{b as comp,k as data};
